//! Types shared by `imbo` and `imbo-server`: REST bodies, WebSocket frames,
//! the problem envelope, the local daemon protocol and a few validators.

pub mod api;
pub mod frames;
pub mod local;
pub mod problem;
pub mod text;

pub use problem::{Candidate, ErrorCode, Problem};

/// Header carrying the acting session, `<tool>:<session_id>`.
pub const HEADER_ACTOR: &str = "imbo-actor-session";
/// Response header with the acting session's unread count.
pub const HEADER_UNREAD: &str = "imbo-unread";
/// Correlation id generated by the daemon for every call.
pub const HEADER_REQUEST_ID: &str = "imbo-request-id";
/// Percent-encoded file name of an upload (API-026).
pub const HEADER_FILE_NAME: &str = "imbo-file-name";
/// SHA-256 of a file, 64 lowercase hex digits (API-026, API-027).
pub const HEADER_FILE_SHA256: &str = "imbo-file-sha256";

pub const TOOL_CLAUDE: &str = "claude-code";
pub const TOOL_CODEX: &str = "codex";
pub const TOOL_OPENCODE: &str = "opencode";
pub const TOOL_CURSOR: &str = "cursor";
pub const TOOL_MCODE: &str = "minimax-code";
pub const TOOL_ZCODE: &str = "zcode";
pub const TOOL_KIMI: &str = "kimi-code";
pub const TOOL_PI: &str = "pi";
pub const TOOL_HERMES: &str = "hermes";
pub const TOOL_DSH: &str = "deepseek-harness";
/// The account's terminal inbox (ADR-010): an `agents` row that is never online.
pub const TOOL_TERMINAL: &str = "terminal";

/// Body limits from the data dictionary.
pub const MAX_BODY_CHARS: usize = 32_000;
pub const INJECT_TRUNCATE_CHARS: usize = 4_000;
pub const MAX_NOTE_CHARS: usize = 200;
pub const MAX_NAME_CHARS: usize = 32;
pub const MAX_GROUP_NAME_CHARS: usize = 64;
pub const MAX_TITLE_CHARS: usize = 200;

/// Attachment limits (INV-012, API-026).
pub const MAX_FILES: usize = 20;
